function render(){let list=state.books.filter(x=>(state.filter==='全部'||x.tag===state.filter)&&(!state.availableOnly||!x.borrower));const recommended=state.books.find(x=>!x.borrower&&(state.filter==='全部'||x.tag===state.filter));$('#app').innerHTML=`<div class="stats">${stat('书架藏书',state.books.length)}${stat('正在借阅',state.books.filter(x=>x.borrower).length)}${stat('可以借阅',state.books.filter(x=>!x.borrower).length)}</div><div class="grid"><div>${panel('下一段冒险，在书架上',`<div class="fields"><label>兴趣标签<select id="filter">${options(['全部',...new Set(state.books.map(x=>x.tag))],state.filter)}</select></label><label class="checkline"><input id="available" type="checkbox" ${state.availableOnly?'checked':''}>只看可借阅</label></div>${list.map(x=>`<div class="item"><div><span class="tag">${esc(x.tag)}</span><h3 style="margin:8px 0">${esc(x.title)}</h3><p>${x.borrower?`由 ${esc(x.borrower)} 借阅 · ${x.date}`:'在架，等待新读者'}</p></div><button data-action="${x.id}" class="small">${x.borrower?'归还':'借阅'}</button></div>`).join('')||empty('当前筛选下没有图书。')}`)}${panel('带一本书来交换',`<form id="book" class="stack">${field('书名','title','text','','required maxlength="80"')}${select('标签','tag',['冒险','科学','童话','自然'])}<button class="primary">加入书架</button></form>`)}</div><div>${panel('为你推荐',recommended?`<span class="tag">规则：匹配标签 + 当前可借</span><h2 style="margin-top:20px">${esc(recommended.title)}</h2><p>这是符合条件的第一本书。试着修改推荐规则，让每个人都能发现不同的书。</p>`:empty('暂无符合条件的在架书。'),'tint')}${panel('借阅者代号',`<label>借阅时使用这个代号<input id="borrower" value="${esc(state.borrower)}" maxlength="20" placeholder="例如：读者 A"></label><p class="notice" style="margin-top:15px">请先填写代号再借书；不用真实姓名。示例书名为课堂原创虚构。</p>`)}</div></div>`;
$('#filter').onchange=e=>{state.filter=e.target.value;commit()};$('#available').onchange=e=>{state.availableOnly=e.target.checked;commit()};$('#borrower').oninput=e=>{state.borrower=e.target.value;save()};actions('[data-action]',id=>{const book=state.books.find(x=>x.id===id);if(book.borrower){book.borrower='';book.date=''}else{if(!state.borrower.trim())return toast('请先填写借阅者代号');book.borrower=state.borrower.trim();book.date=today()}commit()});form('book',v=>{if(state.books.some(x=>x.title===v.title.trim()))return toast('书架里已有这本书');state.books.push({...v,title:v.title.trim(),id:uid(),borrower:'',date:''});commit()})}render();
